// Generates the CP Console's Control Plane API types from the Shared
// control-plane/v1 OpenAPI pinned in contracts.lock.yaml (ADR-BCP-019
// section 38). The input is the Control Plane's embedded copy of that
// description and every file it $refs, which Go tests hold byte-for-byte
// equal to the pinned Shared commit and complete
// (TestEmbeddedContractsMatchShared, TestEmbeddedOpenAPIClosureIsComplete).
//
//   node scripts/generate-cp-client.mjs          rewrite the generated file
//   node scripts/generate-cp-client.mjs --check  fail if it is out of date
//
// The output is reproducible and never edited by hand.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const repository = new URL("../../", import.meta.url);
const input = new URL("internal/contracts/shared/control-plane/v1/openapi.yaml", repository);
const output = new URL("../src/generated/control-plane/openapi.d.ts", import.meta.url);

const lock = await readFile(new URL("contracts.lock.yaml", repository), "utf8");
const commit = /^\s+commit:\s*([0-9a-f]{40})\s*$/m.exec(lock)?.[1];
if (!commit) {
  throw new Error("contracts.lock.yaml does not pin a Shared commit");
}

const ast = await openapiTS(input, { alphabetize: true, defaultNonNullable: false });
const generated = [
  "// Generated by frontend/scripts/generate-cp-client.mjs. Do not edit.",
  `// Source: baobab-platform/shared contracts/control-plane/v1/openapi.yaml at ${commit}`,
  "// (contracts.lock.yaml). Regenerate with: pnpm --filter @baobab-platform/cp-console generate:cp-client",
  "",
  astToString(ast),
].join("\n");

if (process.argv.includes("--check")) {
  const committed = await readFile(output, "utf8").catch(() => "");
  if (committed !== generated) {
    console.error(
      `${fileURLToPath(output)} does not match the pinned OpenAPI. ` +
        "Run pnpm --filter @baobab-platform/cp-console generate:cp-client and commit the result.",
    );
    process.exit(1);
  }
  console.log("generated Control Plane client types match the pinned OpenAPI");
} else {
  await writeFile(output, generated);
  console.log(`wrote ${fileURLToPath(output)}`);
}
